use std::env;
use std::io::{self, IsTerminal};
use std::fs;
use std::path::Path;

const VERSION: &str = "5.2";
const HELP_TEXT: &str = r#"usage: nnn [OPTIONS] [PATH]

The unorthodox terminal file manager.

positional args:
  PATH   start dir/file [default: .]

optional args:
 -a      auto NNN_FIFO
 -A      no dir auto-enter during filter
 -b key  open bookmark key (trumps -s/S)
 -B      use bsdtar for archives
 -c      cli-only NNN_OPENER (trumps -e)
 -C      8-color scheme
 -d      detail mode
 -D      dirs in context color
 -e      text in $VISUAL/$EDITOR/vi
 -E      internal edits in EDITOR
 -f      use history file
 -F val  fifo mode [0:preview 1:explore]
 -g      regex filters
 -H      show hidden files
 -i      show current file info
 -J      no auto-advance on selection
 -K      detect key collision and exit
 -l val  set scroll lines
 -n      type-to-nav mode
 -N      use native prompt
 -o      open files only on Enter
 -p file selection file [-:stdout]
 -P key  run plugin key
 -Q      no quit confirmation
 -r      use advcpmv patched cp, mv
 -R      no rollover at edges
 -s name load session by name
 -S      persistent session
 -t secs timeout to lock
 -T key  sort order [a/d/e/r/s/t/v]
 -u      use selection (no prompt)
 -U      show user and group
 -V      show version
 -x      notis, selection sync, xterm title
 -z      in order fuzzy filters
 -0      null separator in picker mode
 -h      show help

v5.2
BSD 2-Clause
https://github.com/jarun/nnn
"#;

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut path = String::from(".");
    let mut i = 1;
    let mut has_term = io::stdout().is_terminal();
    let mut options = Options::default();

    // Parse arguments
    while i < args.len() {
        let arg = &args[i];

        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            // Handle options
            let chars: Vec<char> = arg.chars().collect();

            if chars[0] != '-' {
                i += 1;
                continue;
            }

            // Check for invalid options starting with --
            if chars.len() > 1 && chars[1] == '-' {
                eprintln!("nnn: invalid option -- '-'");
                print_usage();
                std::process::exit(1);
            }

            for j in 1..chars.len() {
                let opt = chars[j];
                match opt {
                    'V' => {
                        println!("{}", VERSION);
                        std::process::exit(0);
                    }
                    'h' => {
                        print!("{}", HELP_TEXT);
                        std::process::exit(0);
                    }
                    'K' => {
                        // detect key collision and exit
                        std::process::exit(0);
                    }
                    'a' | 'A' | 'c' | 'C' | 'd' | 'D' | 'e' | 'E' 
                    | 'f' | 'g' | 'H' | 'i' | 'J' | 'n' | 'N' | 'o' 
                    | 'Q' | 'r' | 'R' | 'S' | 'u' | 'U' | 'x' | 'z' | 'B' | '0' => {
                        // Flag-only options, store them
                        match opt {
                            'a' => options.auto_fifo = true,
                            'A' => options.no_auto_enter = true,
                            'c' => options.cli_only = true,
                            'C' => options.color_scheme = true,
                            'd' => options.detail_mode = true,
                            'D' => options.dirs_context_color = true,
                            'e' => options.text_editor = true,
                            'E' => options.internal_edits = true,
                            'f' => options.use_history = true,
                            'g' => options.regex_filters = true,
                            'H' => options.show_hidden = true,
                            'i' => options.show_info = true,
                            'J' => options.no_auto_advance = true,
                            'n' => options.type_to_nav = true,
                            'N' => options.native_prompt = true,
                            'o' => options.open_on_enter = true,
                            'Q' => options.no_quit_confirm = true,
                            'r' => options.use_advcpmv = true,
                            'R' => options.no_rollover = true,
                            'S' => options.persistent_session = true,
                            'u' => options.use_selection = true,
                            'U' => options.show_user_group = true,
                            'x' => options.xterm_title = true,
                            'z' => options.fuzzy_filters = true,
                            'B' => options.use_bsdtar = true,
                            '0' => options.null_separator = true,
                            _ => {}
                        }
                    }
                    'b' | 'F' | 'l' | 'p' | 'P' | 's' | 't' | 'T' => {
                        // Options that take arguments
                        i += 1;
                        if i >= args.len() {
                            eprintln!("nnn: option requires an argument -- '{}'", opt);
                            print_usage();
                            std::process::exit(1);
                        }

                        match opt {
                            'b' => options.bookmark_key = Some(args[i].clone()),
                            'F' => options.fifo_mode = Some(args[i].clone()),
                            'l' => options.scroll_lines = Some(args[i].clone()),
                            'p' => options.selection_file = Some(args[i].clone()),
                            'P' => options.plugin_key = Some(args[i].clone()),
                            's' => options.session_name = Some(args[i].clone()),
                            't' => options.timeout = Some(args[i].clone()),
                            'T' => options.sort_order = Some(args[i].clone()),
                            _ => {}
                        }
                    }
                    _ => {
                        eprintln!("nnn: invalid option -- '{}'", opt);
                        print_usage();
                        std::process::exit(1);
                    }
                }
            }
        } else {
            // Positional argument (path)
            path = arg.clone();
        }

        i += 1;
    }

    // If not a terminal, print "0 entries" and exit
    if !has_term {
        println!("0 entries");
        std::process::exit(if options.sort_order.is_some() { 1 } else { 0 });
    }

    // For now, just exit gracefully
    std::process::exit(0);
}

#[derive(Default)]
struct Options {
    auto_fifo: bool,
    no_auto_enter: bool,
    cli_only: bool,
    color_scheme: bool,
    detail_mode: bool,
    dirs_context_color: bool,
    text_editor: bool,
    internal_edits: bool,
    use_history: bool,
    regex_filters: bool,
    show_hidden: bool,
    show_info: bool,
    no_auto_advance: bool,
    type_to_nav: bool,
    native_prompt: bool,
    open_on_enter: bool,
    no_quit_confirm: bool,
    use_advcpmv: bool,
    no_rollover: bool,
    persistent_session: bool,
    use_selection: bool,
    show_user_group: bool,
    xterm_title: bool,
    fuzzy_filters: bool,
    use_bsdtar: bool,
    null_separator: bool,

    bookmark_key: Option<String>,
    fifo_mode: Option<String>,
    scroll_lines: Option<String>,
    selection_file: Option<String>,
    plugin_key: Option<String>,
    session_name: Option<String>,
    timeout: Option<String>,
    sort_order: Option<String>,
}

fn print_usage() {
    print!("{}", HELP_TEXT);
}
EOF

